0,"Create a Python script that accepts a directory path and a target file extension as input arguments. The script should recursively traverse the specified directory, identify all files with the given extension, and convert them to a new format using an external library or tool. The converted files should be saved in the same directory with the same filenames but with the new file extension appended. The script should return 0 if all conversions are successful, else return 1. It should handle any errors from the external library/tool without propagating them to the user.",78,,"['```python
import os
import sys
from external_library import convert_file

def batch_convert_files(directory_path, target_extension):
    for root, _, files in os.walk(directory_path):
        for file_name in files:
            if file_name.endswith(target_extension):
                input_file_path = os.path.join(root, file_name)
                output_file_path = os.path.splitext(input_file_path)[0] + '_converted' + target_extension
                try:
                    convert_file(input_file_path, output_file_path)
                except Exception as e:
                    print(f""Error converting {input_file_path}: {e}"")
                    return 1
    return 0

if __name__ == ""__main__"":
    if len(sys.argv) != 3:
        print(""Usage: python script.py <directory_path> <target_extension>"")
        sys.exit(1)

    directory_path = sys.argv[1]
    target_extension = sys.argv[2]

    result = batch_convert_files(directory_path, target_extension)
    sys.exit(result)
