import hashlib

class SHA256Exception(Exception):
    pass

def calculateSHA256(data: str, returnHex: bool) -> str:
    if not data:
        raise SHA256Exception(""Input string cannot be null or empty"")

    try:
        sha_signature = hashlib.sha256(data.encode()).digest()
        if returnHex:
            return sha_signature.hex()
        else:
            return sha_signature
    except Exception as e:
        raise SHA256Exception(f""Error occurred during hashing: {e}"")

# Unit tests
import unittest

class TestSHA256HashFunction(unittest.TestCase):
    def test_valid_input(self):
        result = calculateSHA256(""hello world"", True)
        self.assertTrue(isinstance(result, str))
        self.assertEqual(len(result), 64)

    def test_empty_string(self):
        with self.assertRaises(SHA256Exception) as context:
            calculateSHA256("""", False)
        self.assertIn(""Input string cannot be null or empty"", str(context.exception))

    def test_exception_handling(self):
        with self.assertRaises(SHA256Exception) as context:
            calculateSHA256(None, True)
        self.assertIn(""Input string cannot be null or empty"", str(context.exception))

if __name__ == ""__main__"":
    unittest.main()
