def encrypt_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def modify_kickstart_config(config_path, replacements):
    try:
        with open(config_path, 'r') as config_file:
            config_data = config_file.read()

        for placeholder, value in replacements.items():
            config_data = config_data.replace(f""${placeholder}"", str(value))

        encrypted_password = encrypt_password(replacements['password'])
        config_data += f""\npassword={encrypted_password}""

        new_config_path = f""{config_path}.modified""
        with open(new_config_path, 'w') as new_config_file:
            new_config_file.write(config_data)

        return new_config_path

    except Exception as e:
        raise e
