def parse_user_data(line):
    # Extract user data from the line using regular expressions
    data = {}
    match = re.search(r'Name:(\w+)', line)
    if match:
        data['name'] = match.group(1)
    match = re.search(r'Email:(\w+@\w+\.\w+)', line)
    if match:
        data['email'] = match.group(1)
    match = re.search(r'Password:(\w+)', line)
    if match:
        data['password'] = match.group(1)
    return data

def update_user_account(user_id, name=None, email=None, password=None):
    # Logic to update user account in the database
    print(f""Updating user with ID {user_id} - Name: {name}, Email: {email}, Password: {password}"")

def delete_user_account(user_id):
    # Logic to delete user account from the database
    print(f""Deleting user with ID {user_id}"")
```

