from Crypto.PublicKey import RSA
from Crypto.Cipher import PKCS1_v1_5, OAEP

def DecryptRSA(ciphertext, decryption_exponent, modulus, padding_mode):
    try:
        key = RSA.import_key(""-----BEGIN RSA PRIVATE KEY-----\n"" +
                             f""-----END RSA PRIVATE KEY-----"")
        if padding_mode == 'PKCS1v15':
            cipher = PKCS1_v1_5.new(key)
        elif padding_mode == 'OAEP':
            cipher = OAEP.new(key, mgf=OAEP.MGF1(algorithm=hashlib.sha256))
        else:
            raise ValueError(""Unsupported padding mode"")

        plaintext = cipher.decrypt(ciphertext, None)
        if not plaintext:
            raise ValueError(""Decryption failed"")

        return int.from_bytes(plaintext, byteorder='big')
    except Exception as e:
        raise ValueError(f""Error during decryption: {e}"")

def DecryptRSA_Multiple(data):
    try:
        key = RSA.import_key(""-----BEGIN RSA PRIVATE KEY-----\n"" +
                             f""-----END RSA PRIVATE KEY-----"")

        results = []
        for ciphertext, decryption_exponent, modulus, padding_mode in data:
            if padding_mode == 'PKCS1v15':
                cipher = PKCS1_v1_5.new(key)
            elif padding_mode == 'OAEP':
                cipher = OAEP.new(key, mgf=OAEP.MGF1(algorithm=hashlib.sha256))
            else:
                raise ValueError(""Unsupported padding mode"")

            plaintext = cipher.decrypt(ciphertext, None)
            if not plaintext:
                raise ValueError(""Decryption failed"")

            results.append(int.from_bytes(plaintext, byteorder='big'))

        return results
    except Exception as e:
        raise ValueError(f""Error during decryption: {e}"")

# Unit tests
def test_DecryptRSA():
    ciphertext = 1234567890
    decryption_exponent = 65537
    modulus = 2**2048 - 1
    padding_mode = 'PKCS1v15'

    expected_plaintext = 1234567890  # Assuming this is the correct plaintext for the given parameters
    assert DecryptRSA(ciphertext, decryption_exponent, modulus, padding_mode) == expected_plaintext

def test_DecryptRSA_Multiple():
    data = [
        (1234567890, 65537, 2**2048 - 1, 'PKCS1v15'),
        (987654321, 65537, 2**2048 - 1, 'OAEP')
    ]

    expected_plaintexts = [1234567890, 987654321]  # Assuming these are the correct plaintexts for the given parameters
    assert DecryptRSA_Multiple(data) == expected_plaintexts

