from Crypto.PublicKey import RSA
from Crypto.Random import get_random_bytes
from Crypto.Cipher import AES, HMAC
from Crypto.Hash import SHA3_256
import hashlib

class CryptoModule:
    def __init__(self):
        self.keys = {}

    def register_algorithm(self, algorithm_name):
        if algorithm_name == ""SHA3"":
            return SHA3_256.new()
        elif algorithm_name == ""HMAC"":
            return HMAC.new(key=get_random_bytes(16), msg=b'', digestmod=SHA3_256)
        elif algorithm_name == ""AES"":
            return AES.new(key=get_random_bytes(16), mode=AES.MODE_CBC)

    def unregister_algorithm(self, algorithm):
        pass

    def generate_key(self, key_size=2048):
        return RSA.generate(key_size)

    def encrypt_data(self, data, key, iv=None):
        if not iv:
            iv = get_random_bytes(AES.block_size)
        cipher = AES.new(key, AES.MODE_CBC, iv)
        return iv + cipher.encrypt(data)

    def decrypt_data(self, encrypted_data, key, iv=None):
        if not iv:
            iv = encrypted_data[:AES.block_size]
            encrypted_data = encrypted_data[AES.block_size:]
        cipher = AES.new(key, AES.MODE_CBC, iv)
        return cipher.decrypt(encrypted_data).rstrip(b'\0')

    def create_hmac(self, data, key):
        hmac_obj = HMAC.new(key=key, msg=data, digestmod=SHA3_256)
        return hmac_obj.hexdigest()

    def verify_hmac(self, data, hmac, key):
        try:
            hmac_obj = HMAC.new(key=key, msg=data, digestmod=SHA3_256)
            hmac_obj.verify(hmac)
            return True
        except ValueError:
            return False

    def create_hash(self, data, digest_size=256):
        hash_obj = SHA3_256.new(data.encode())
        return hash_obj.hexdigest()[:digest_size]

# Command-line interface for user interaction
def main():
    crypto_module = CryptoModule()

    while True:
        print(""\n1. Generate Key"")
        print(""2. Encrypt Data"")
        print(""3. Decrypt Data"")
        print(""4. Create HMAC"")
        print(""5. Verify HMAC"")
        print(""6. Create Hash"")
        print(""7. Exit"")

        choice = input(""Enter your choice: "")

        if choice == '1':
            key_size = int(input(""Enter key size (default 2048): "") or 2048)
            key = crypto_module.generate_key(key_size)
            print(f""Generated Key: {key}"")
        elif choice == '2':
            data = input(""Enter data to encrypt: "")
            key = bytes.fromhex(input(""Enter encryption key in hex: ""))
            iv = bytes.fromhex(input(""Enter initialization vector in hex (optional): "") or '')
            encrypted_data = crypto_module.encrypt_data(data.encode(), key, iv)
            print(f""Encrypted Data: {encrypted_data.hex()}"")
        elif choice == '3':
            encrypted_data_hex = input(""Enter encrypted data in hex: "")
            encrypted_data = bytes.fromhex(encrypted_data_hex)
            key = bytes.fromhex(input(""Enter decryption key in hex: ""))
            iv = bytes.fromhex(input(""Enter initialization vector in hex (optional): "") or '')
            decrypted_data = crypto_module.decrypt_data(encrypted_data, key, iv)
            print(f""Decrypted Data: {decrypted_data.decode()}"")
        elif choice == '4':
            data = input(""Enter data to create HMAC: "")
            key = bytes.fromhex(input(""Enter HMAC key in hex: ""))
            hmac_value = crypto_module.create_hmac(data.encode(), key)
            print(f""HMAC: {hmac_value}"")
        elif choice == '5':
            data = input(""Enter data to verify HMAC: "")
            hmac_to_verify = input(""Enter HMAC value to verify: "")
            key = bytes.fromhex(input(""Enter HMAC key in hex: ""))
            is_valid = crypto_module.verify_hmac(data.encode(), hmac_to_verify, key)
            print(f""HMAC Valid: {is_valid}"")
        elif choice == '6':
            data = input(""Enter data to create hash: "")
            digest_size = int(input(""Enter digest size (default 256): "") or 256)
            hash_value = crypto_module.create_hash(data, digest_size)
            print(f""Hash: {hash_value}"")
        elif choice == '7':
            break
        else:
            print(""Invalid choice. Please try again."")

if __name__ == ""__main__"":
    main()
```

