import subprocess

def merge_and_activate_email_server(server_path, server_name):
    ssl_settings_file = 'ssl_settings.ini'

    if not (server_path / ssl_settings_file).exists():
        return None

    command = f""subprocess.check_output(['activate_email_server', '{server_name}', '{server_path}'])""

    try:
        result = subprocess.run(command.split(), capture_output=True, text=True)

        if result.returncode == 0:
            return f""Email Server {server_name} successfully activated at {server_path}.""
        else:
            return f""Failed to activate Email Server {server_name}. Error: {result.stderr}""

merge_and_activate_email_server('/path/to/server', 'ExampleServer')
merge_and_activate_email_server('/path/to/missing/server', 'MissingServer')
