import socket
import random
import struct

def construct_sock_addr(ip_ranges, port_numbers, protocol_family, fsa, last_state):
    # Validate input parameters
    if not ip_ranges or not port_numbers or not fsa or last_state is None:
        raise ValueError(""Invalid input parameters"")

    # Generate random host addresses within specified IP ranges
    socket_addresses = []
    for ip_range in ip_ranges:
        start_ip, end_ip = map(int, ip_range.split('-'))
        while len(socket_addresses) < len(ip_ranges):
            random_ip = random.randint(start_ip, end_ip)
            try:
                socket.inet_ntoa(struct.pack(""!I"", random_ip))
                socket_addresses.append((socket.inet_ntoa(struct.pack(""!I"", random_ip)), random.choice(port_numbers), protocol_family))
            except socket.error:
                continue

    return socket_addresses
