import random

class DeviceProfile:
    def __init__(self, device_id, mac_address, operational_state):
        self.device_id = device_id
        self.mac_address = mac_address
        self.operational_state = operational_state

def generate_mac_address():
    return ':'.join(""%02x"" % random.randint(0, 255) for _ in range(6))

def get_random_operational_state():
    states = [""active"", ""inactive"", ""suspended""]
    return random.choice(states)

def create_device_profiles(num_devices):
    profiles = []
    for i in range(num_devices):
        device_id = f""device_{i+1}""
        mac_address = generate_mac_address()
        operational_state = get_random_operational_state()
        profile = DeviceProfile(device_id, mac_address, operational_state)
        profiles.append(profile)
    return profiles

# Example usage
profiles = create_device_profiles(5)
for profile in profiles:
    print(f""Device ID: {profile.device_id}, MAC Address: {profile.mac_address}, State: {profile.operational_state}"")
