import subprocess
import hashlib
import re

def encrypt_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def validate_password_strength(password):
    if len(password) < 8:
        return False, ""Password must be at least 8 characters long.""
    if not any(char.isdigit() for char in password):
        return False, ""Password must contain at least one digit.""
    if not any(char.isalpha() for char in password):
        return False, ""Password must contain at least one letter.""
    if not any(char.islower() for char in password):
        return False, ""Password must contain at least one lowercase letter.""
    if not any(char.isupper() for char in password):
        return False, ""Password must contain at least one uppercase letter.""
    return True, """"

def modify_kickstart_config(config_path, replacements):
    try:
        with open(config_path, 'r') as config_file:
            config_data = config_file.read()

        valid_password, message = validate_password_strength(replacements['password'])
        if not valid_password:
            raise ValueError(message)

        for placeholder, value in replacements.items():
            config_data = config_data.replace(f""${placeholder}"", str(value))

        encrypted_password = encrypt_password(replacements['password'])

        # Check for existing password line and replace it if present
        password_pattern = re.compile(r'password=(\S+)')
        match = password_pattern.search(config_data)

        if match:
            existing_password = match.group(1)
            new_config_data = config_data[:match.start()] + f""password={encrypted_password}"" + config_data[match.end():]
            # Verify that the original encrypted password matches the existing line before replacement
            original_encrypted_match = encrypt_password(existing_password) == encrypted_password
            if original_encrypted_match:
                new_config_path = f""{config_path}.modified""
                with open(new_config_path, 'w') as new_config_file:
                    new_config_file.write(new_config_data)
                return new_config_path
            else:
                raise ValueError(""Existing encrypted password does not match."")

        else:
            new_config_path = f""{config_path}.modified""
            with open(new_config_path, 'w') as new_config_file:
                new_config_file.write(f""{config_data}\npassword={encrypted_password}"")

            # Create a backup of the original configuration file after modification
            subprocess.run(['cp', '-a', config_path, f'{config_path}.bak'])
            return new_config_path

    except Exception as e:
        print(f""An error occurred: {e}"")
        return None
