from typing import List

def advanced_insert_or_replace(strings_list: List[str], search_str: str, insert_str: str, overwrite=False) -> None:
    found_index = -1

    # Find the first occurrence of search_str
    for i, string in enumerate(strings_list):
        if string == search_str:
            found_index = i
            break

    # If not found and overwrite is True, find the last occurrence
    if found_index == -1 and overwrite:
        for i in range(len(strings_list) - 1, -1, -1):
            if strings_list[i] == search_str:
                found_index = i
                break

    # Insert insert_str immediately after found_index
    if found_index != -1:
        strings_list.insert(found_index + 1, insert_str)
    else:
        # Append insert_str at the end of the list if not found and no overwrite
        strings_list.append(insert_str)
