0,"Design a Python function that takes a list of distinct positive integers as input, calculates the count of unique pairs within the list whose combined sum is a prime number, and outputs the duration in milliseconds required to identify these unique pairs. The function should solely leverage standard library functionalities and ensure that the input list contains no repeated elements.",330,,"['```python
import time

def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def count_unique_pairs_with_prime_sum(numbers):
    start_time = time.time()
    unique_pairs = set()
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if is_prime(numbers[i] + numbers[j]):
                smaller, larger = sorted([numbers[i], numbers[j]])
                unique_pairs.add((smaller, larger))
    end_time = time.time()
    return len(unique_pairs), (end_time - start_time) * 1000

# Example usage
input_list = [2, 3, 5, 7, 11]
pair_count, duration_ms = count_unique_pairs_with_prime_sum(input_list)
print(f""Unique pairs with prime sum: {pair_count}, Duration in ms: {duration_ms}"")
```']",0,[0],[],True,0,0,0,

