import psycopg2
from psycopg2 import pool

class NetworkConnectionPool:
    _pool = None

    @staticmethod
    def get_connection_pool(minconn=1, maxconn=10):
        if NetworkConnectionPool._pool is None:
            NetworkConnectionPool._pool = psycopg2.pool.SimpleConnectionPool(
                minconn, maxconn,
                database=""your_database"",
                user=""your_user"",
                password=""your_password"",
                host=""your_host"",
                port=""your_port""
            )
        return NetworkConnectionPool._pool

    @staticmethod
    def fetch_data(query):
        connection_pool = NetworkConnectionPool.get_connection_pool()
        if connection_pool:
            conn = connection_pool.getconn()
            try:
                cursor = conn.cursor()
                cursor.execute(query)
                results = cursor.fetchall()
                return results
            except Exception as e:
                print(f""Error fetching data: {e}"")
            finally:
                cursor.close()
                connection_pool.putconn(conn)
        return None

# Example usage
if __name__ == ""__main__"":
    query = ""SELECT * FROM your_table""
    results = NetworkConnectionPool.fetch_data(query)
    if results:
        for row in results:
            print(row)
```

