import threading
import requests
from oauthlib.oauth2 import BackendApplicationClient
from requests_oauthlib import OAuth2Session
import json
import base64
from cryptography.hazmat.primitives.serialization import load_pem_private_key, load_pem_certificate
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric.padding import PKCS1v15
from functools import lru_cache
import logging

# Setup logging configuration
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class KeyCertificateFetcher:
    def __init__(self, client_id, client_secret):
        self.client_id = client_id
        self.client_secret = client_secret
        self.oauth_client = BackendApplicationClient(client_id=client_id)
        self.token = None

    @lru_cache(maxsize=128)  # Cache access tokens for 128 different clients
    def fetch_access_token(self):
        oauth = OAuth2Session(client=self.oauth_client)
        token_url = 'https://oauth.example.com/token'  # Replace with actual token URL
        token = oauth.fetch_token(token_url, client_id=self.client_id, client_secret=self.client_secret)
        return token

    def validate_oauth_request(self, oauth_params):
        required_keys = ['grant_type', 'scope']
        if not all(key in oauth_params for key in required_keys):
            raise ValueError(""OAuth request is missing required parameters"")
        if oauth_params['grant_type'] != 'client_credentials':
            raise ValueError(""Invalid grant type"")
        return True

    def fetch_private_key(self, token_url, token):
        headers = {'Authorization': f'Bearer {token}'}
        response = requests.get(token_url, headers=headers)
        response.raise_for_status()
        private_key_pem = base64.b64decode(response.json()['private_key'])
        return load_pem_private_key(private_key_pem, password=None)

    def fetch_certificate(self, token_url, token):
        headers = {'Authorization': f'Bearer {token}'}
        response = requests.get(token_url, headers=headers)
        response.raise_for_status()
        certificate_pem = base64.b64decode(response.json()['certificate'])
        return load_pem_certificate(certificate_pem)

    def fetch_keys_certificates(self, oauth_params):
        if not self.validate_oauth_request(oauth_params):
            raise ValueError(""Invalid OAuth request"")

        token = self.fetch_access_token()
        threads = []
        results = {}

        for scope in oauth_params.get('scope', '').split():
            thread = threading.Thread(target=self._fetch_keys_certificates_for_scope, args=(scope, token, results))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

        return results

    def _fetch_keys_certificates_for_scope(self, scope, token, results):
        try:
            token_url = f'https://api.example.com/{scope}/keys'  # Replace with actual API endpoint
            private_key = self.fetch_private_key(token_url, token)
            certificate_url = f'https://api.example.com/{scope}/certificate'
            certificate = self.fetch_certificate(certificate_url, token)

            results[scope] = {
                'private_key': private_key.private_bytes(
                    encoding=serialization.Encoding.PEM,
                    format=serialization.PrivateFormat.TraditionalOpenSSL,
                    encryption_algorithm=serialization.NoEncryption()
                ),
                'certificate': certificate.public_bytes(serialization.Encoding.PEM)
            }
        except Exception as e:
            logging.error(f""Failed to fetch keys/certificate for scope {scope}: {e}"")
            results[scope] = None

# Example usage
if __name__ == ""__main__"":
    client_id = 'your_client_id'
    client_secret = 'your_client_secret'
    fetcher = KeyCertificateFetcher(client_id, client_secret)
    oauth_params = {
        'grant_type': 'client_credentials',
        'scope': 'api1 api2'
    }
    keys_certificates = fetcher.fetch_keys_certificates(oauth_params)
    for scope, data in keys_certificates.items():
        if data:
            logging.info(f""Successfully fetched keys and certificate for scope {scope}"")
            print(data['private_key'])
            print(data['certificate'])
        else:
            logging.warning(f""No valid keys or certificate found for scope {scope}"")
