import json
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
from Crypto.Random import get_random_bytes
import hashlib

class SecureJSONHandler:
    _registry = {}

    @classmethod
    def register_factory(cls, subclass_id, factory_func):
        cls._registry[subclass_id] = factory_func

    @classmethod
    def create_instance(cls, subclass_id, *args, **kwargs):
        if subclass_id in cls._registry:
            return cls._registry[subclass_id](*args, **kwargs)
        raise ValueError(f""Subclass ID {subclass_id} not registered"")

    def to_json(self, data):
        return json.dumps(data)

    @staticmethod
    def from_json(json_string):
        return json.loads(json_string)

    @classmethod
    def encrypt_file(cls, file_path, encryption_algorithm='md5', key=None, salt=None):
        with open(file_path, 'rb') as file:
            content = file.read()

        if encryption_algorithm == 'md5':
            hash_obj = hashlib.md5(content)
            digest = hash_obj.digest()
        else:
            raise ValueError(""Unsupported encryption algorithm"")

        if not key:
            raise ValueError(""Symmetric key must be provided for AES-CBC encryption"")

        cipher = AES.new(key, AES.MODE_CBC, salt)
        encrypted_digest = cipher.encrypt(pad(digest, AES.block_size))
        return encrypted_digest.hex(), cipher

# Example usage
class MySecureClass(SecureJSONHandler):
    pass

SecureJSONHandler.register_factory('my_secure_class', MySecureClass)

# Create an instance of MySecureClass using the factory function
instance = SecureJSONHandler.create_instance('my_secure_class')

# Convert data to JSON
data = {'key': 'value'}
json_data = instance.to_json(data)
print(json_data)

# Encrypt a file
file_path = 'example.txt'
encrypted_hash, cipher = SecureJSONHandler.encrypt_file(file_path, key=get_random_bytes(16), salt=get_random_bytes(AES.block_size))
print(f""Encrypted Hash: {encrypted_hash}"")
```

