0,"Create a new programming task that computes and validates the SHA-256 hash of files. The task should include a function, `compute_file_sha256`, which calculates the SHA-256 hash of a given file using specified chunk sizes (default is 64 kilobytes). Another function, `verify_file_sha256`, should take a file path and an expected SHA-256 hash as parameters, compare the computed hash with the expected one, and indicate any discrepancies. Finally, the script should test these functions on a list of predefined file paths and their expected SHA-256 hashes.",328,,"['```python
import hashlib

def compute_file_sha256(file_path, chunk_size=64*1024):
    sha256_hash = hashlib.sha256()
    with open(file_path, ""rb"") as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            sha256_hash.update(data)
    return sha256_hash.hexdigest()

def verify_file_sha256(file_path, expected_hash):
    computed_hash = compute_file_sha256(file_path)
    if computed_hash == expected_hash:
        print(f""Hash verified: {file_path}"")
        return True
    else:
        print(f""Hash verification failed for {file_path}. Expected {expected_hash}, got {computed_hash}"")
        return False

# Test the functions
test_files = [
    (""path/to/file1.txt"", ""expected_sha256_hash_1""),
    (""path/to/file2.txt"", ""expected_sha256_hash_2"")
]

for file_path, expected_hash in test_files:
    verify_file_sha256(file_path, expected_hash)
