import random

class PlayingCard:
    SUITS = ['Hearts', 'Diamonds', 'Clubs', 'Spades']
    RANKS = ['2', '3', '4', '5', '6', '7', '8', '9', '10', 'Jack', 'Queen', 'King', 'Ace']

    def __init__(self, rank, suit):
        self.rank = rank
        self.suit = suit

    def __str__(self):
        return f""{self.rank} of {self.suit}""

class DeckOfCards:
    def __init__(self):
        self.cards = [PlayingCard(rank, suit) for suit in PlayingCard.SUITS for rank in PlayingCard.RANKS]

    def shuffle(self):
        random.shuffle(self.cards)

    def deal_card(self):
        return self.cards.pop()

    def display_deck(self):
        print(""\n"".join(str(card) for card in self.cards))

# Example usage
deck = DeckOfCards()
deck.shuffle()
print(""Shuffled deck:"")
deck.display_deck()
first_card = deck.deal_card()
print(f""\nDealt card: {first_card}"")
print(""\nRemaining deck:"")
deck.display_deck()
