import hashlib

class InvalidInputError(Exception):
    pass

def calculateSHA256(data: str, returnHex: bool) -> str:
    if not data:
        raise InvalidInputError(""Input string cannot be null or empty"")

    try:
        sha_signature = hashlib.sha256(data.encode()).hexdigest() if returnHex else hashlib.sha256(data.encode()).digest()
        return sha_signature
    except Exception as e:
        raise ValueError(f""An error occurred while hashing the data: {str(e)}"")

# Unit tests

def test_calculateSHA256():
    # Test with valid string and hexadecimal output
    assert calculateSHA256(""hello"", True) == hashlib.sha256(""hello"".encode()).hexdigest()

    # Test with valid string and binary output
    assert calculateSHA256(""world"", False) == hashlib.sha256(""world"".encode()).digest()

    # Test with empty string
    try:
        calculateSHA256("""", True)
    except InvalidInputError as e:
        assert str(e) == ""Input string cannot be null or empty""

    # Test with None input
    try:
        calculateSHA256(None, True)
    except InvalidInputError as e:
        assert str(e) == ""Input string cannot be null or empty""

    # Test with non-string input
    try:
        calculateSHA256(123, True)
    except ValueError as e:
        assert str(e).startswith(""An error occurred while hashing the data"")

test_calculateSHA256()
