import argparse
import os

def parse_arguments():
    parser = argparse.ArgumentParser(description='Recursively count files in the given directory.')
    parser.add_argument('-h', '--help', action='store_true', help='Display this help message and exit')
    parser.add_argument('-o', '--output', type=str, help='Output directory for count results')
    parser.add_argument('input_dir', type=str, help='Input directory to count files in', nargs='?', default=os.getcwd())
    return parser.parse_args()

def is_hidden(path):
    return os.path.basename(path).startswith('.') or os.path.islink(path)

def count_files(input_dir, output_dir=None):
    total_files = 0
    for root, dirs, files in os.walk(input_dir):
        for file in files:
            if not is_hidden(os.path.join(root, file)):
                total_files += 1
        # Exclude hidden directories as well
        dirs[:] = [d for d in dirs if not is_hidden(os.path.join(root, d))]
    if output_dir:
        with open(os.path.join(output_dir, 'file_count.txt'), 'w') as f:
            f.write(f'Total files: {total_files}')
    else:
        print(f'Total files: {total_files}')

def main():
    args = parse_arguments()

    if args.help:
        print(parser.format_help())
        return

    count_files(args.input_dir, args.output)

if __name__ == '__main__':
    main()
