import hashlib
import os
from concurrent.futures import ThreadPoolExecutor

class FileHashCalculator:
    def computeSHA256Checksum(self, file_obj):
        try:
            sha256 = hashlib.sha256()
            while True:
                data = file_obj.read(4096)
                if not data:
                    break
                sha256.update(data)
            return sha256.hexdigest()
        except FileNotFoundError:
            raise ValueError(""File not found."")
        except IOError as e:
            raise ValueError(f""Error reading the file: {e}"")
        except Exception as e:
            raise ValueError(f""An unexpected error occurred: {e}"")

    def checkHash(self, file_path):
        try:
            with open(file_path, 'rb') as f_obj:
                return self.computeSHA256Checksum(f_obj)
        except Exception as e:
            print(f""Error occurred during hash verification: {e}"")

    def computeChecksums(self, files_list):
        results = {}
        for file_obj in files_list:
            try:
                results[file_obj.name] = self.computeSHA256Checksum(file_obj)
            except Exception as e:
                results[file_obj.name] = str(e)
        return results

    def computeChecksums_parallel(self, files_list, processes=4):
        results = {}
        with ThreadPoolExecutor(max_workers=processes) as executor:
            future_to_file = {executor.submit(self.computeSHA256Checksum, file): file for file in files_list}
            for future in concurrent.futures.as_completed(future_to_file):
                try:
                    results[future_to_file[future]] = future.result()
                except Exception as exc:
                    results[future_to_file[future]] = str(exc)
        return results
