import random
from Crypto.Cipher import AES
import hashlib

class NFA_API_CRC_INDICATION_PDU_T:
    def __init__(self, rx_ue_information_tag, rnti, crc_indication_rel8_tag):
        self.rx_ue_information_tag = rx_ue_information_tag
        self.rnti = rnti
        self.crc_indication_rel8_tag = crc_indication_rel8_tag

def generate_random_crf_flag():
    return random.choice([True, False])

def create_nfa_api_pdu(rx_ue_information_tag, rnti):
    crc_ind_flag = generate_random_crf_flag()
    crc_indication_rel8_tag = {""crc_flag"": crc_ind_flag}
    nfa_api_pdu = NFA_API_CRC_INDICATION_PDU_T(rx_ue_information_tag, rnti, crc_indication_rel8_tag)
    return nfa_api_pdu

def aes_encrypt(data, key):
    cipher = AES.new(key, AES.MODE_ECB)
    pad_len = AES.block_size - len(data) % AES.block_size
    padded_data = data + chr(pad_len).encode() * pad_len
    encrypted_data = cipher.encrypt(padded_data)
    return encrypted_data

def md5_hash(data):
    hash_object = hashlib.md5()
    hash_object.update(data)
    return hash_object.digest()

def generate_nfaapi(nfa_api_pdu, key):
    serialized_data = NFA_API_CRC_INDICATION_PDU_T.serialize_to_byte_array(nfa_api_pdu)
    encrypted_data = aes_encrypt(serialized_data + nfa_api_pdu.crc_indication_rel8_tag['crc_flag'].to_bytes(1, 'big'), key)
    md5_hashed_data = md5_hash(encrypted_data)

    return encrypted_data + b'\n' + md5_hashed_data

class SerializeDeserialize:

    @staticmethod
    def serialize_to_byte_array(obj):
        import pickle
        return pickle.dumps(obj)

    @staticmethod
    def deserialize_from_byte_array(byte_array):
        import pickle
        return pickle.loads(byte_array)

class MD5HashGenerator:

    @staticmethod
    def generate_md5_hash(file_path):
        with open(file_path, 'rb') as file:
            data = file.read()
        hash_object = hashlib.md5()
        hash_object.update(data)
        return hash_object.digest()

# Enhanced function to merge packet creation and encryption with security checks.
def advanced_secure_transmission(data: str, rx_ue_info: str, rnti: int, key: bytes) -> bytes:
    nfa_api_pdu = create_nfa_api_pdu(rx_ue_info.encode(), rnti)
    serialized_packet = SerializeDeserialize.serialize_to_byte_array(nfa_api_pdu)
    encrypted_packet_with_md5 = generate_nfaapi(serialized_packet + data.encode(), key)
    file_md5_check_value = MD5HashGenerator.generate_md5_hash(""file_path_here"")

    md5_hashed_part_of_packet = encrypted_packet_with_md5[-16:]
    if file_md5_check_value == md5_hashed_part_of_packet:
        return encrypted_packet_with_md5
    else:
        raise ValueError(""File integrity check failed. Packet cannot be transmitted."")
