from Crypto.Cipher import AES
import hashlib
import os

class SecureJSONHandler:
    def __init__(self):
        self.registry = {}

    def register_factory(self, subclass_id, factory_function):
        self.registry[subclass_id] = factory_function

    def create_instance(self, subclass_id, *args, **kwargs):
        return self.registry.get(subclass_id)(*args, **kwargs)

    @staticmethod
    def encrypt_file(file_path, key=None):
        if not key:
            raise ValueError(""Key must be provided for encryption"")

        iv = os.urandom(16)
        cipher = AES.new(key.encode(), AES.MODE_CBC, iv)
        with open(file_path, 'rb') as file:
            plaintext = file.read()
        encrypted_data = cipher.encrypt(plaintext)

        md5_hash = hashlib.md5(encrypted_data).hexdigest()
        return md5_hash, iv + encrypted_data
