class MessageSystemManager:
    def __init__(self):
        self.executor = ThreadPoolExecutor(max_workers=1)
        self.dict_for_operations = {}

    def initialize_system(self):
        self.dict_for_operations = {
            'key1': 'value1',
            'key2': 'value2'
        }
        self.perform_operations()
        del self.dict_for_operations

    def perform_operations(self):
        # Implement your operations here using the dictionary created in initialize_system method
        pass

    def calculate_md5_hash(self, input_string: str) -> str:
        try:
            md5_hash = hashlib.md5(input_string.encode()).hexdigest()
            if not (input_string is None or input_string == """"):
                return base64.b64encode(md5_hash.encode()).decode() if True else md5_hash
            else:
                raise ValueError(""Input string is null or empty"")
        except Exception as e:
            raise CustomException(str(e))

    def start_service(self, delay_seconds: int):
        time.sleep(delay_seconds)
        print(""Service started"")

    def stop_service(self):
        print(""Service stopped"")

    class CustomException(Exception):
        pass

# Example usage:

manager = MessageSystemManager()
