def is_prime(num):
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def filter_prime_numbers(numbers):
    prime_numbers = [num for num in numbers if is_prime(num)]
    sum_of_primes = sum(prime_numbers)
    return prime_numbers, sum_of_primes

# Example usage:
