import aiofiles

class FileManager:
    def __init__(self, max_open_files, buffer_size):
        self.max_open_files = max_open_files
        self.buffer_size = buffer_size
        self.open_files = set()
        self.file_buffers = {}
        self.file_process_results = {}

    async def create_file_manager(self):
        if not hasattr(self, 'file_manager'):
            self.file_manager = aiofiles.os.open('datafile.txt', 'w+b', buffering=self.buffer_size)
            return True
        return False

    async def open_file(self, file_name):
        if len(self.open_files) < self.max_open_files:
            file_path = f'{file_name}.txt'
            try:
                async with aiofiles.open(file_path, mode='r') as file:
                    self.open_files.add(file_path)
                    return await file.read()
            except FileNotFoundError:
                print(f'File {file_name} not found.')
                return None
            finally:
                await asyncio.sleep(1)
                print(f'File {file_name} closed.')
                if file_path in self.open_files:
                    self.open_files.remove(file_path)
                    del self.file_buffers[file_path]
                    del self.file_process_results[file_path]
        else:
            print('Maximum number of open files reached.')
            return None

    async def read_data_async(self, data_criteria):
