```python
import hashlib

def compute_md5(file_path):
    hash_md5 = hashlib.md5()
    with open(file_path, ""rb"") as f:
        for chunk in iter(lambda: f.read(4096), b""""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def compare_md5(file_path, expected_hash):
    computed_hash = compute_md5(file_path)
    if computed_hash == expected_hash:
        print(f""The MD5 hash of {file_path} is correct."")
    else:
        print(f""The MD5 hash of {file_path} is incorrect. Expected: {expected_hash}, got: {computed_hash}"")

