def convertAndEncode(inputValue, conversionType, paddingLength):
    try:
        if conversionType == ""binary"":
            output = format(inputValue, 'b')
        elif conversionType == ""octal"":
            output = format(inputValue, 'o')
        elif conversionType == ""hexadecimal"":
            output = format(inputValue, 'x').upper()
        else:
            raise ValueError(""Invalid conversion type. Please use 'binary', 'octal', or 'hexadecimal'."")

        if not isinstance(paddingLength, int) or paddingLength < 0:
            raise ValueError(""Padding length must be a non-negative integer."")

        padded_output = output.zfill(paddingLength)
        return padded_output

    except (TypeError, OverflowError):
        raise ValueError(""Input value must be an integer."")

# Unit tests
def test_convertAndEncode():
    assert convertAndEncode(10, ""binary"", 8) == ""00001010""
    assert convertAndEncode(255, ""octal"", 4) == ""377""
    assert convertAndEncode(255, ""hexadecimal"", 6) == ""00ff""

    try:
        convertAndEncode(""10"", ""binary"", 8)
    except ValueError as e:
        assert str(e) == ""Input value must be an integer.""

    try:
        convertAndEncode(10, ""decimal"", 8)
    except ValueError as e:
        assert str(e) == ""Invalid conversion type. Please use 'binary', 'octal', or 'hexadecimal'.""

    try:
        convertAndEncode(10, ""binary"", -1)
    except ValueError as e:
        assert str(e) == ""Padding length must be a non-negative integer.""

test_convertAndEncode()
