def remove_substrings(strings, substrings_to_remove):
    pattern = '|'.join(map(re.escape, substrings_to_remove))
    return [re.sub(pattern, '', s) for s in strings]

def interactive_interface():
    strings = []
    while True:
        user_input = input(""Enter a string (or 'done' to finish): "")
        if user_input.lower() == 'done':
            break
        strings.append(user_input)

    substrings_to_remove = input(""Enter sub-strings to remove separated by spaces: "").split()

    updated_strings = remove_substrings(strings, substrings_to_remove)

    print(""\nUpdated list of strings:"")
    for s in updated_strings:
        print(s)

if __name__ == ""__main__"":
    interactive_interface()
