import networkx as nx

def generate_weighted_graph(num_vertices):
    graph = nx.Graph()
    for i in range(num_vertices):
        for j in range(i+1, num_vertices):
            weight = random.randint(1, 10)  # Generate a random weight between 1 and 10
            graph.add_edge(i, j, weight=weight)
    return graph

def generate_nfaapi_crc_indication_pdu(file_path):
    with open(file_path, 'r') as file:
        lines = file.readlines()

    pdu_array = []
    for line in lines:
        data = line.strip().split(',')
        rx_ue_info = int(data[0])
        rnti_value = int(data[1])
        boolean_flag = bool(int(data[2]))

        pdu = NFAPI_CRC_INDICATION_PDU_T(rx_ue_info, rnti_value, boolean_flag)
        pdu_array.append(pdu)

    return pdu_array

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, rx_ue_info, rnti_value, boolean_flag):
        self.rx_ue_info = rx_ue_info
        self.rnti_value = rnti_value
        self.boolean_flag = boolean_flag

    def validate(self):
        if self.rx_ue_info <= 0 or self.rnti_value < 1 or not isinstance(self.boolean_flag, bool):
            return False
        return True

def compute_shortest_paths(graph):
    shortest_paths = {}
    for node in graph.nodes:
        paths = nx.single_source_dijkstra_path_length(graph, source=node)
        shortest_paths[node] = paths
    return shortest_paths

def process_files(file_paths, shortest_paths):
    optimized_paths = []
    for file_path in file_paths:
        pdu_array = generate_nfaapi_crc_indication_pdu(file_path)
        valid_pdus = [pdu for pdu in pdu_array if pdu.validate()]

        if not valid_pdus:
            continue

        source_node = valid_pdus[0].rx_ue_info
        target_nodes = set(pdu.rx_ue_info for pdu in valid_pdus[1:])

        shortest_path_lengths = {node: shortest_paths[source_node][node] for node in target_nodes}
        optimal_path = min(shortest_path_lengths, key=shortest_path_lengths.get)

        optimized_paths.append((source_node, optimal_path))

    return optimized_paths
