class DataValidator:
    def validateData(self, data, schema):
        try:
            for item in data:
                if not isinstance(item, dict):
                    raise TypeError(""Each element in data must be a dictionary."")
                for key, required_type in schema.items():
                    if key not in item:
                        raise KeyError(f""Missing required field '{key}'"")
                    if not isinstance(item[key], required_type):
                        raise ValueError(f""Field '{key}' must be of type {required_type.__name__}"")
            return True
        except (TypeError, KeyError, ValueError) as e:
            print(e)
            return False

