import re

def remove_substrings(text_list, substrings_to_remove):
    return [re.sub('|'.join(map(re.escape, substrings_to_remove)), '', text) for text in text_list]

def main():
    text_list = [""Hello world"", ""world of programming"", ""remove these words""]
    print(""Original list:"", text_list)

    while True:
        substring_to_remove = input(""Enter a substring to remove (or type 'done' to finish): "")
        if substring_to_remove.lower() == 'done':
            break
        text_list = remove_substrings(text_list, [substring_to_remove])
        print(""Updated list:"", text_list)

if __name__ == ""__main__"":
    main()
