0,"Create a new function, `encryptData`, that accepts a string and an integer key. This function employs the `CustomCipher` class to encrypt the input string using the specified key. The `CustomCipher` class features methods for generating a random salt, creating a unique encryption key based on the provided key and salt, and applying this encryption to the input string. The function should manage errors by logging them to a file or showing them in the console, ensuring encryption can still happen even when there are temporary issues. Moreover, include functionality within `encryptData` to enable decryption of data using the same process in reverse, providing a full encryption and decryption suite within your application.",590,,"['```python
import logging
from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes

class CustomCipher:
    def __init__(self):
        self.log_file = 'encryption_errors.log'

    def log_error(self, error_message):
        with open(self.log_file, 'a') as file:
            file.write(error_message + '\n')

    def generate_salt(self):
        return get_random_bytes(16)

    def create_encryption_key(self, key, salt):
        derived_key = hashlib.pbkdf2_hmac('sha256', key.encode(), salt, 100000)
        return derived_key

    def encrypt_data(self, data, key):
        try:
            salt = self.generate_salt()
            encryption_key = self.create_encryption_key(key, salt)
            cipher = AES.new(encryption_key, AES.MODE_GCM)
            ciphertext, tag = cipher.encrypt_and_digest(data.encode())
            encrypted_data = {'salt': salt, 'ciphertext': ciphertext, 'tag': tag}
            return encrypted_data
        except Exception as e:
            self.log_error(f'Encryption error: {str(e)}')

    def decrypt_data(self, encrypted_data, key):
        try:
            encryption_key = self.create_encryption_key(key, encrypted_data['salt'])
            cipher = AES.new(encryption_key, AES.MODE_GCM, nonce=encrypted_data['nonce'], mac_len=AES.block_size)
            decrypted_data = cipher.decrypt_and_verify(encrypted_data['ciphertext'], encrypted_data['tag'])
            return decrypted_data.decode()
        except Exception as e:
            self.log_error(f'Decryption error: {str(e)}')

def encryptData(data, key):
    custom_cipher = CustomCipher()
    encrypted_data = custom_cipher.encrypt_data(data, key)
    if not encrypted_data:
        print(""Encryption failed."")
        return None
    else:
        return encrypted_data

def decryptData(encrypted_data, key):
    custom_cipher = CustomCipher()
    decrypted_data = custom_cipher.decrypt_data(encrypted_data, key)
    if not decrypted_data:
        print(""Decryption failed."")
        return None
    else:
        return decrypted_data
```

