3,"Develop a function that validates an API response containing a JSON object with keys for 'status', 'statusCode', 'message', and 'data'. The function should check if the response is successful (i.e., statusCode is 200), the status key exists, the message key exists, and the data key exists. Additionally, it should validate that the message is not empty, data is of a specific type (e.g., array or object), and provide an error message if any of these conditions are not met.",798,,"['```python
def validate_api_response(response):
    expected_keys = ['status', 'statusCode', 'message', 'data']
    required_types = {
        'message': str,
        'data': list  # or dict, depending on the expected data type
    }

    if not isinstance(response, dict):
        return ""Error: Response is not a JSON object.""

    for key in expected_keys:
        if key not in response:
            return f""Error: Missing '{key}' key in response.""

    if response['statusCode'] != 200:
        return ""Error: API request was unsuccessful.""

    if not isinstance(response['message'], required_types['message']):
        return f""Error: 'message' should be of type {required_types['message']}.""

    if not isinstance(response['data'], required_types['data']):
        return f""Error: 'data' should be of type {required_types['data']}.""

    if response['message'].strip() == '':
        return ""Error: Message cannot be empty.""

    return ""API response is valid.""
