def process_tuples(tuples_list):
    # Create a dictionary from the list of tuples
    my_dict = dict(tuples_list)

    # Iterate through the dictionary and convert string values to uppercase
    for key, value in my_dict.items():
        if isinstance(value, str):
            my_dict[key] = value.upper()

    # Remove entries where the value is longer than 10 characters
    my_dict = {key: value for key, value in my_dict.items() if len(value) <= 10}

    return my_dict

