import random
import numpy as np
import matplotlib.pyplot as plt

class Dice:
    def __init__(self, sides=6, probabilities=None):
        self.sides = sides
        if probabilities is None:
            self.probabilities = [1/sides] * sides
        else:
            self.probabilities = probabilities

    def roll(self):
        return np.random.choice(range(1, self.sides + 1), p=self.probabilities)

class DiceSet:
    def __init__(self):
        self.dice = []

    def add_die(self, die):
        self.dice.append(die)

    def roll_all(self):
        results = [die.roll() for die in self.dice]
        return sum(results)

class GameCharacter:
    def __init__(self, attributes=None):
        if attributes is None:
            self.attributes = {'strength': 50, 'agility': 50}
        else:
            self.attributes = attributes

    def roll_strength(self):
        return Dice(20, [self.attributes['strength'] / 100] * 20).roll()

    def roll_agility(self):
        return Dice(20, [self.attributes['agility'] / 100] * 20).roll()

class AIOpponent:
    def __init__(self, difficulty='easy'):
        self.difficulty = difficulty

    def roll(self):
        if self.difficulty == 'easy':
            return random.randint(1, 6)
        elif self.difficulty == 'medium':
            return random.randint(1, 8)
        else:
            return random.randint(1, 10)

class DiceSimulationApp:
    def __init__(self):
        self.dice_set = DiceSet()
        self.history = []

    def add_die(self, sides, probabilities=None):
        die = Dice(sides, probabilities)
        self.dice_set.add_die(die)

    def roll_dice(self):
        result = self.dice_set.roll_all()
        self.history.append((self.dice_set.dice, result))
        return result

    def calculate_statistics(self):
        results = [roll for _, roll in self.history]
        mean = np.mean(results)
        median = np.median(results)
        mode = max(set(results), key=results.count)
        std_dev = np.std(results)
        return mean, median, mode, std_dev

    def plot_histogram(self):
        results = [roll for _, roll in self.history]
        plt.hist(results, bins=max(self.dice_set.dice, key=lambda x: x.sides).sides + 1)
        plt.xlabel('Roll Result')
        plt.ylabel('Frequency')
        plt.title('Dice Roll Histogram')
        plt.show()

    def create_character(self):
        return GameCharacter()

    def play_game(self, character):
        print(f""Strength Roll: {character.roll_strength()}"")
        print(f""Agility Roll: {character.roll_agility()}"")

    def train_ai_opponent(self, difficulty='easy'):
        self.ai_opponent = AIOpponent(difficulty)

    def ai_roll(self):
        return self.ai_opponent.roll()

# Example usage
app = DiceSimulationApp()
app.add_die(6)
app.add_die(8)
character = app.create_character()
app.train_ai_opponent('medium')
app.play_game(character)
result = app.roll_dice()
print(f""Total Roll: {result}"")
mean, median, mode, std_dev = app.calculate_statistics()
app.plot_histogram()
```']",0,[0],[],True,0,0,0,

