class DiceRollSimulation:
    def __init__(self, seed=None):
        self.rng = random.Random()
        if seed:
            self.rng.seed(seed)
        self.dice = {}
        self.customers = {}
        self.stats = {
            'mean': 0,
            'median': 0,
            'mode': 0,
            'std_dev': 0
        }
        self.history = []

    def add_dice(self, dice_type, num_sides, probabilities):
        if num_sides < 2 or num_sides > 100:
            raise ValueError(""Number of sides must be between 2 and 100"")

        if sum(probabilities) != 100:
            raise ValueError(""Probabilities must sum up to 100%"")

        for outcome, prob in enumerate(probabilities):
            if prob < 1 or prob > 99:
                raise ValueError(""Probability must be between 1% and 99%"")

        self.dice[dice_type] = {'num_sides': num_sides, 'probabilities': probabilities}

    def add_customers(self, customer_id, attributes):
        if not isinstance(attributes, dict) or not all(isinstance(key, str) for key in attributes.keys()):
            raise ValueError(""Customer attributes must be a dictionary with string keys"")

        for attr_name in attributes.keys():
            if attr_name not in ['strength', 'agility']:
                raise ValueError(""Invalid attribute name"")

        self.customers[customer_id] = {'attributes': attributes}

    def roll_dice(self):
        outcomes = []

        for dice_type in self.dice.keys():
            roll_result = self.rng.choices(
                list(range(1, self.dice[dice_type]['num_sides'] + 1)),
                weights=self.dice[dice_type]['probabilities']
            )

            outcomes.extend(roll_result)

        return outcomes
