import hashlib
import os

def async_file_hasher(file_path, callback, chunk_size=4096):
    # Initialize an empty byte string for accumulation
    accumulation = b''
    hash_obj = hashlib.md5()
    try:
        # Open the file for reading in binary mode
        with open(file_path, 'rb') as f:
            while True:
                chunk = f.read(chunk_size)
                if not chunk:
                    break
                # Accumulate chunks while updating hash
                accumulation += chunk
                hash_obj.update(chunk)
        # Pass accumulated bytes and current hash state to callback, including the final hash object for comparison or further processing
        callback(accumulation, hash_obj.hexdigest())
    except Exception as e:
        # In case of error during processing or file reading
        return str(e)

