class CustomEncryptionHelper:
    def __init__(self, shift=3):
        self.shift = shift

    def encrypt(self, text):
        encrypted_text = """"
        for char in text:
            if char.isalpha():
                shift_base = ord('a') if char.islower() else ord('A')
                new_char = chr((ord(char) - shift_base + self.shift) % 26 + shift_base)
                encrypted_text += new_char
            else:
                encrypted_text += char
        return encrypted_text

    def decrypt(self, text):
        decrypted_text = """"
        for char in text:
            if char.isalpha():
                shift_base = ord('a') if char.islower() else ord('A')
                new_char = chr((ord(char) - shift_base - self.shift) % 26 + shift_base)
                decrypted_text += new_char
            else:
                decrypted_text += char
        return decrypted_text

    def __str__(self):
        return f""CustomEncryptionHelper with shift: {self.shift}""
